HEAD = '<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="24dp" android:height="24dp" android:viewportWidth="24" android:viewportHeight="24">'
os.makedirs(OUT, exist_ok=True)
for line in DATA.strip().splitlines():
    name, paths = line.split("|", 1)
    xml = HEAD
    for p in paths.split(";;"):
        code, d = p.split(":", 1)
        sw = code[:-4]
        cap, join, fill, stroke = code[-4], code[-3], code[-2], code[-1]
        t = '<path android:pathData="%s"' % d
        if fill == "F": t += ' android:fillColor="#FF000000"'
        if stroke == "S":
            t += ' android:strokeColor="#FF000000" android:strokeWidth="%s"' % sw
            if cap == "r": t += ' android:strokeLineCap="round"'
            if join == "r": t += ' android:strokeLineJoin="round"'
        xml += t + "/>"
    xml += "</vector>"
    with open(os.path.join(OUT, name + ".xml"), "w") as f:
        f.write(xml + "\n")
print("generated", len(DATA.strip().splitlines()), "icons")
